begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('f0000000-0000-4000-8000-000000000007','mpesa-test-cashier@pedigree.local'),
 ('f0000000-0000-4000-8000-000000000008','mpesa-test-manager@pedigree.local'),
 ('f0000000-0000-4000-8000-000000000009','mpesa-test-other@pedigree.local');
update public.pos_users set auth_user_id='f0000000-0000-4000-8000-000000000007' where id='a1c9f1e2-0000-4000-8000-000000000001';
update public.pos_users set auth_user_id='f0000000-0000-4000-8000-000000000008' where id='a1c9f1e2-0000-4000-8000-000000000002';
insert into public.pos_users(id,auth_user_id,name,pin_hash,role) values('f3040000-0000-4000-8000-000000000009','f0000000-0000-4000-8000-000000000009','Other fixture',extensions.crypt('8412',extensions.gen_salt('bf',4)),'cashier');
insert into public.products(id,name,slug,category,base_price) values('f3000000-0000-4000-8000-000000000001','M-Pesa SQL fixture','mpesa-sql-fixture','bag',3500);
insert into public.product_colors(id,product_id,color_name,color_hex,stock_quantity) values('f3010000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Tan','#8B4513',10);
create function pg_temp.prepare(p_id uuid default 'f3020000-0000-4000-8000-000000000001',p_total integer default 3500) returns jsonb language sql as $$
 select public.pos_prepare_mpesa_sale(p_id,p_total,'[{"product_id":"f3000000-0000-4000-8000-000000000001","color_id":"f3010000-0000-4000-8000-000000000001","quantity":1,"price_at_sale":3500}]');
$$;
create function pg_temp.attempt(p_id uuid default 'f3030000-0000-4000-8000-000000000001',p_amount integer default 3500) returns jsonb language sql as $$
 select public.pos_begin_mpesa_attempt(p_id,'f3020000-0000-4000-8000-000000000001','a1c9f1e2-0000-4000-8000-000000000001','254712345678',p_amount,repeat('a',64));
$$;
create function pg_temp.callback(p_hash text default repeat('a',64),p_amount integer default 3500,p_phone text default '254712345678') returns void language sql as $$
 select public.pos_store_mpesa_callback('f3030000-0000-4000-8000-000000000001',p_hash,'mpesa-sql-checkout','mpesa-sql-merchant',0,p_amount,p_phone,'PGTEST0001');
$$;
select ok(not has_function_privilege('anon','public.pos_prepare_mpesa_sale(uuid,integer,jsonb)','execute'),'anon cannot prepare payments');
select ok(not has_function_privilege('authenticated','public.pos_apply_mpesa_callback(uuid,integer)','execute'),'cashier cannot apply callback');
select ok(not has_function_privilege('authenticated','public.pos_store_mpesa_callback(uuid,text,text,text,integer,integer,text,text)','execute'),'cashier cannot forge callback evidence');
select set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000007',true);
select set_config('request.jwt.claim.role','authenticated',true);
set local role authenticated;
select throws_ok($$select pg_temp.prepare(gen_random_uuid(),1)$$,'22023','total_mismatch','server prices the draft');
select is((pg_temp.prepare()->>'saleId')::uuid,'f3020000-0000-4000-8000-000000000001'::uuid,'draft prepared');
select is((pg_temp.prepare()->>'amount')::integer,3500,'draft replay uses canonical amount');
select is((select stock_quantity from public.product_colors where id='f3010000-0000-4000-8000-000000000001'),10,'draft does not decrement stock');
select throws_ok($$select pg_temp.attempt()$$,'42501',null,'browser cannot dispatch via privileged RPC');
select throws_ok($$select public.pos_record_sale('f3020000-0000-4000-8000-000000000001','a1c9f1e2-0000-4000-8000-000000000001',3500,'mpesa',null,'[]')$$,'42501','not_authorized','unverified client cannot mark M-Pesa paid');
reset role;
select set_config('request.jwt.claim.role','service_role',true);
set local role service_role;
select throws_ok($$select pg_temp.attempt(gen_random_uuid(),1)$$,'22023','invalid_payment','dispatch rejects client amount mismatch');
select is((pg_temp.attempt()->>'dispatch')::boolean,true,'service claims one attempt');
select is((pg_temp.attempt()->>'dispatch')::boolean,false,'same request does not dispatch twice');
select throws_ok($$select pg_temp.attempt(gen_random_uuid())$$,'22023','payment_unresolved','second unresolved payment blocked');
select lives_ok($$select public.pos_attach_mpesa_request('f3030000-0000-4000-8000-000000000001','mpesa-sql-merchant','mpesa-sql-checkout')$$,'provider ids saved');
select throws_ok($$select pg_temp.callback(repeat('b',64))$$,'42501','invalid_callback','wrong capability rejected');
select throws_ok($$select pg_temp.callback(repeat('a',64),1)$$,'22023','callback_mismatch','wrong callback amount rejected');
select throws_ok($$select pg_temp.callback(repeat('a',64),3500,'254711111111')$$,'22023','callback_mismatch','wrong phone rejected');
select is(public.pos_apply_mpesa_callback('f3030000-0000-4000-8000-000000000001',0),'reconciliation','provider query alone cannot finalize without callback');
select is((select count(*)::integer from public.pos_sales where client_uuid='f3020000-0000-4000-8000-000000000001'),0,'no paid sale without callback');
reset role;
select set_config('request.jwt.claim.role','authenticated',true);
set local role authenticated;
select is((select count(*)::integer from public.pos_mpesa_transactions where id='f3030000-0000-4000-8000-000000000001'),1,'owner can poll own attempt');
select throws_ok($$select callback_token_hash from public.pos_mpesa_transactions$$,'42501',null,'callback hash is not browser-readable');
select throws_ok($$select phone_number from public.pos_mpesa_transactions$$,'42501',null,'poll projection excludes phone');
select throws_ok($$update public.pos_mpesa_transactions set status='success'$$,'42501',null,'direct status writes denied');
select lives_ok($$select public.pos_note_manual_mpesa('f3030000-0000-4000-8000-000000000001','MANUAL0001')$$,'manual code can be recorded');
select is((select status from public.pos_mpesa_transactions where id='f3030000-0000-4000-8000-000000000001'),'manual_pending','manual code is not success');
select is((select count(*)::integer from public.pos_sales where client_uuid='f3020000-0000-4000-8000-000000000001'),0,'manual code creates no paid sale');
select throws_ok($$select public.pos_cancel_mpesa_draft('f3020000-0000-4000-8000-000000000001')$$,'22023','payment_unresolved','cash fallback cannot cancel unresolved funds');
reset role;
select set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000009',true);
set local role authenticated;
select is((select count(*)::integer from public.pos_mpesa_transactions where id='f3030000-0000-4000-8000-000000000001'),0,'other cashier cannot read attempt');
select throws_ok($$select public.pos_note_manual_mpesa('f3030000-0000-4000-8000-000000000001','MANUAL0002')$$,'42501','not_authorized','other cashier cannot edit manual code');
reset role;
update public.products set base_price=4500,active=false where id='f3000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.role','service_role',true);
set local role service_role;
select lives_ok($$select pg_temp.callback()$$,'valid callback evidence persisted');
select is(public.pos_apply_mpesa_callback('f3030000-0000-4000-8000-000000000001',0),'success','verified callback finalizes sale');
select is((select total from public.pos_sales where id='f3020000-0000-4000-8000-000000000001'),3500,'captured server price is immutable across catalogue changes');
select is((select payment_method from public.pos_sales where id='f3020000-0000-4000-8000-000000000001'),'mpesa','sale method is M-Pesa');
select is((select stock_quantity from public.product_colors where id='f3010000-0000-4000-8000-000000000001'),9,'verified completion decrements once');
select is(public.pos_apply_mpesa_callback('f3030000-0000-4000-8000-000000000001',0),'success','callback replay returns original success');
select lives_ok($$select pg_temp.callback()$$,'repeated valid callback is a no-op');
select is((select stock_quantity from public.product_colors where id='f3010000-0000-4000-8000-000000000001'),9,'replay does not decrement twice');
select is((select count(*)::integer from public.stock_movements where reason='sale:f3020000-0000-4000-8000-000000000001'),1,'one sale ledger movement');
select is((select event from public.pos_sale_audit where sale_id='f3020000-0000-4000-8000-000000000001'),'mpesa_sale_recorded','M-Pesa sale has audit');
reset role;
set local role anon;
select throws_ok($$select * from public.pos_mpesa_transactions$$,'42501',null,'anon cannot read attempts');
reset role;
select * from finish();
rollback;
